# The mutations of Wolly.Passkey, sourced by scripts/mutate.sh.
mutations+=(
	"Passkey.hiq|s/if not (userPresent(flags) and userVerified(flags)) then/if not userPresent(flags) then/|a user who was not verified passes"
	"Passkey.hiq|s/if not (userPresent(flags) and userVerified(flags)) then/if not userVerified(flags) then/|a user who was not present passes"
	"Passkey.hiq|s/                if not same then/                if false then/|authenticator data of another party passes"
	"Passkey.hiq|s/                fits := equal(asSpan(\&found), kind);/                fits := true;/|client data of the other type passes"
	"Passkey.hiq|s/                if cross then/                if false then/|cross-origin client data passes"
	"Passkey.hiq|s/        if not sameOrigin then/        if false then/|another origin passes"
	"Passkey.hiq|s/            if columnInt64(\&cursor, 1) >= now then/            if true then/|a challenge that ran out passes"
	"Passkey.hiq|s/            if columnInt64(\&cursor, 1) >= now then/            if columnInt64(\&cursor, 1) > now then/|a challenge at its last second is refused"
	"Passkey.hiq|s/:= \"DELETE FROM wolly_passkey_challenges WHERE challenge = ? AND purpose = ? RETURNING name, expires_at\";/:= \"SELECT name, expires_at FROM wolly_passkey_challenges WHERE challenge = ? AND purpose = ?\";/|a challenge is used twice"
	"Passkey.hiq|s/                        if same then/                        if true then/|a challenge of another name passes a registration"
	"Passkey.hiq|s/        if not equal(owner, who) then/        if false then/|a challenge of another name passes a login"
	"Passkey.hiq|s/if not isText(document, format, \"none\") then/if false then/|another format than none passes"
	"Passkey.hiq|s/if not isEmptyMap(document, statement) then/if false then/|a statement passes"
	"Passkey.hiq|s/        if not isMap(document, item) then/        if false then/|an empty array passes as no statement"
	"Passkey.hiq|s/                return pairs = 0;/                return true;/|a statement with pairs passes"
	"Passkey.hiq|s/if (not hasCredential(flags)) or hasExtensions(flags) then/if hasExtensions(flags) then/|authenticator data without a credential is read"
	"Passkey.hiq|s/if (not hasCredential(flags)) or hasExtensions(flags) then/if not hasCredential(flags) then/|extensions are read as the key"
	"Passkey.hiq|s/if ((kty = 2) and (alg = -7)) and (crv = 1) then/if (kty = 2) and (crv = 1) then/|a P-256 key without an alg passes"
	"Passkey.hiq|s/if ((kty = 1) and (alg = -8)) and (crv = 6) then/if (kty = 1) and (crv = 6) then/|an Ed25519 key without an alg passes"
	"Passkey.hiq|s/                if fits then/                if true then/|a signature that does not fit passes"
	"Passkey.hiq|s/WHERE credential = ? AND (sign_count < ? OR/WHERE credential = ? AND (sign_count <= ? OR/|the same counter passes twice"
	"Passkey.hiq|s/                                if changed = 0 then/                                if false then/|a credential known is taken again"
)
